
-- Batch 12: Remaining South Africa, South Korea, Spain, Sudan, Syria, Tanzania, Thailand, Tunisia, Turkey, Uganda, UK, US/USA, Uzbekistan, Venezuela, Vietnam, West Africa, Zambia, Zimbabwe, Zanzibar
UPDATE recipes SET continent = 'Africa', history = 'Umngqusho (Samp and Beans) is a traditional Xhosa dish that was reportedly Nelson Mandela''s favorite food. This hearty combination of dried corn kernels and sugar beans has sustained South African communities for generations and represents the country''s indigenous food heritage.' WHERE slug = 'umngqusho-samp-beans-south-africa';

UPDATE recipes SET continent = 'Africa', history = 'Vetkoek with Mince is a classic South African comfort food of deep-fried bread filled with savory ground meat. This dish has Dutch colonial origins and has been embraced by all South African communities. Vetkoek represents the beloved tradition of filling fried bread with whatever is available.' WHERE slug = 'vetkoek-mince-south-africa';

UPDATE recipes SET continent = 'Africa', history = 'Walkie-Talkies (Chicken Feet and Heads) are a popular South African township street food. This nose-to-tail tradition represents the resourcefulness of South African urban communities and the African philosophy that every part of an animal should be used and celebrated.' WHERE slug = 'walkie-talkies-chicken-feet-south-africa';

UPDATE recipes SET continent = 'Asia', history = 'Whipped Coffee (Dalgona) became a global phenomenon during the 2020 COVID-19 lockdowns, originating from South Korea. Named after Korean honeycomb toffee, this whipped instant coffee drink became the most-searched recipe worldwide and represents Korea''s cultural influence in the social media age.' WHERE slug = 'whipped-coffee-dalgona';

UPDATE recipes SET continent = 'Europe', history = 'Gazpacho is an Andalusian cold soup with ancient Roman origins. Chef John''s version pays homage to this refreshing tomato-based soup that has sustained Spanish farmers during hot summers for centuries. Gazpacho represents the Mediterranean tradition of celebrating raw, ripe vegetables.' WHERE slug = 'chef-johns-gazpacho';

UPDATE recipes SET continent = 'Africa', history = 'Kisra with Mullah is Sudan''s staple meal, pairing thin sorghum flatbread (kisra) with okra stew. Kisra has been made in Sudan for millennia, using sorghum—one of Africa''s oldest domesticated grains. This dish represents the agricultural heritage of the Nile Valley and Sudan''s unique culinary identity.' WHERE slug = 'kisra-mullah-okra-sudan';

UPDATE recipes SET continent = 'Asia', history = 'Stuffed Grape Leaves (Yalanji) are a beloved Syrian dish that dates back to the Ottoman Empire. The technique of wrapping rice and herb fillings in grape leaves spread across the Mediterranean and Middle East. Syrian versions feature pomegranate molasses and walnuts, reflecting the country''s refined cuisine.' WHERE slug = 'stuffed-grape-leaves-sy';

UPDATE recipes SET continent = 'Africa', history = 'Mkate Mayai is a Tanzanian egg bread, a sweet, pancake-like street food popular in Dar es Salaam. This fluffy, egg-rich bread represents the creative street food culture of Tanzania, where vendors transform simple ingredients into delicious affordable snacks.' WHERE slug = 'mkate-mayai';

UPDATE recipes SET continent = 'Africa', history = 'Urojo (Zanzibar Mix) is a unique Zanzibari soup combining multiple components—crispy bhajias, boiled potatoes, and eggs in a tangy coconut-tamarind broth. This complex dish represents the multilayered culinary heritage of Zanzibar, where African, Arab, Indian, and Persian flavors converge.' WHERE slug = 'urojo-zanzibar-mix-tanzania';

UPDATE recipes SET continent = 'Asia', history = 'Mango Sticky Rice (Khao Niaow Ma Muang) is Thailand''s most famous dessert, combining sweet glutinous rice with ripe mango and coconut cream. This beloved treat is deeply tied to Thailand''s mango season and represents the Thai genius of balancing sweetness, saltiness, and richness.' WHERE slug = 'mango-sticky-rice-th';

UPDATE recipes SET continent = 'Asia', history = 'Som Tum (Green Papaya Salad) is one of Thailand''s most iconic dishes, originally from the Isan (northeastern) region. This spicy, tangy salad of shredded unripe papaya showcases the Thai balance of flavors: sour, sweet, salty, spicy, and umami. It''s now Thailand''s most popular salad.' WHERE slug = 'som-tum-th';

UPDATE recipes SET continent = 'Asia', history = 'Thai Mango Avocado Salad is a modern fusion celebrating Thailand''s tropical fruit abundance. Thailand is one of the world''s largest mango producers, and this contemporary salad combines traditional Thai flavor profiles with health-conscious modern presentations.' WHERE slug = 'thai-mango-avocado-salad-th';

UPDATE recipes SET continent = 'Asia', history = 'Tom Yum Goong is Thailand''s most famous soup, a spicy and sour shrimp broth that embodies the Thai philosophy of balanced flavors. Named "the most delicious soup in the world," tom yum features lemongrass, galangal, and kaffir lime leaves—the holy trinity of Thai aromatics.' WHERE slug = 'tom-yum-goong-th';

UPDATE recipes SET continent = 'Asia', history = 'Pad Thai is Thailand''s most recognized dish globally, created during WWII-era nationalism to promote Thai identity. Despite its relatively recent invention, pad thai perfectly embodies Thailand''s culinary philosophy of balancing sweet, sour, salty, and spicy flavors in every bite.' WHERE slug = 'pad-thai-thailand';

UPDATE recipes SET continent = 'Asia', history = 'Spicy Coconut Grilled Chicken blends Thai flavors with American grilling culture. Coconut milk has been used in Thai cooking for centuries, and this fusion dish represents the global influence of Thai cuisine on contemporary American home cooking.' WHERE slug = 'spicy-coconut-grilled-chicken';

UPDATE recipes SET continent = 'Europe', history = 'Baklava is a rich, sweet pastry of phyllo layers filled with nuts and honey syrup. Its origins are claimed by Turkey, Greece, and the Arab world, with roots in the Ottoman Empire. Turkish baklava from Gaziantep is considered the finest and was granted EU geographical indication status.' WHERE slug = 'baklava-tr';

UPDATE recipes SET continent = 'Europe', history = 'Dolmades (Stuffed Grape Leaves) trace their origins to Ottoman cuisine and are beloved across Turkey, Greece, and the Middle East. The Turkish version (dolma) features rice, pine nuts, and currants wrapped in tender vine leaves. This dish represents the shared culinary heritage of the Ottoman world.' WHERE slug = 'dolmades-tr';

UPDATE recipes SET continent = 'Africa', history = 'Kafteji is a Tunisian vegetable dish of fried peppers, tomatoes, and pumpkin mixed with eggs. This colorful, flavorful dish represents the North African tradition of transforming humble vegetables into satisfying meals. Kafteji showcases Tunisia''s Mediterranean and Berber culinary heritage.' WHERE slug = 'kafteji-tunisia';

UPDATE recipes SET continent = 'Africa', history = 'Katogo is Uganda''s traditional breakfast stew of cooking bananas (matoke) with beans, groundnuts, or offal. This hearty morning meal reflects the importance of the East African highland banana in Ugandan cuisine and the tradition of starting the day with a substantial, nourishing dish.' WHERE slug = 'katogo-uganda';

UPDATE recipes SET continent = 'Africa', history = 'Luwombo is a traditional Ugandan dish steamed in banana leaves, created by the personal chef of Kabaka Mwanga II of Buganda in the 19th century. This royal dish, where meat and groundnut sauce are sealed and steamed in banana leaves, represents the sophisticated culinary traditions of the Buganda Kingdom.' WHERE slug = 'luwombo-steamed-uganda';

UPDATE recipes SET continent = 'Africa', history = 'Matoke (Banana Stew) is a Ugandan staple made from cooking bananas, which are culturally and nutritionally central to the country. Uganda is one of the world''s largest banana producers, and matoke is eaten daily across the country. The dish represents Uganda''s unique banana-centered food culture.' WHERE slug = 'matoke-banana-stew-uganda';

UPDATE recipes SET continent = 'Africa', history = 'Matoke with Beef Stew is the quintessential Ugandan meal, pairing steamed cooking bananas with a rich beef stew. This combination represents the heart of Ugandan home cooking and the country''s agricultural abundance in the fertile highland regions.' WHERE slug = 'matoke-with-beef-stew';

UPDATE recipes SET continent = 'Africa', history = 'Ugandan Rolex is the country''s most famous street food, a chapati rolled around a fried egg omelet. Created in the early 2000s in Kampala, "Rolex" is a playful abbreviation of "rolled eggs." This ingenious snack represents the vibrant creativity of East African street food culture.' WHERE slug = 'ugandan-rolex';

UPDATE recipes SET continent = 'Africa', history = 'Malewa (Smoked Bamboo Shoots) is a delicacy from eastern Uganda, where bamboo forests grow on the slopes of Mount Elgon. The Bagisu people harvest and smoke bamboo shoots to create this unique dish, which represents the foraging traditions of Uganda''s mountain communities.' WHERE slug = 'malewa-smoked-bamboo-uganda';

UPDATE recipes SET continent = 'Europe', history = 'Cheddar and Chive Scones are a beloved British baking tradition. Scones date back to 16th century Scotland, and the addition of cheddar cheese and chives creates a savory version perfect for afternoon tea. This recipe represents the quintessential British home baking culture.' WHERE slug = 'cheddar-scones-uk';
